def S(t, viz=None, h=None, sw=None, tipo="Gráfica + lecturas", estado=None, cierre=False):
    return dict(t=t, viz=viz, h=h or [], sw=sw, tipo=tipo, estado=estado, cierre=cierre)

def CIERRE(t, h, sw=None):
    return S(t, viz="Cierre: cadena de causas (5 porqués), hipótesis analítica, operativa y de gobierno, cómo (semana, dónde en Braze, equipo, métrica) y qué ganamos.", h=h, sw=sw, tipo="Cierre de sección", cierre=True)

def DIV(t):
    return S(t, tipo="Divisor de acto")

